fn putI32(out:[*]u8,off:usize,x:i64)void{const b=@as(u32,@bitCast(@as(i32,@intCast(x))));for(0..4)|k|out[off+k]=@truncate(b>>(8*k));}
export fn operators(v:[*]const i64,n:usize,out:[*]u8,cap:usize)i64{if(n<5)return -1;const op=v[0];const ra=v[1];const ca=v[2];if((op!=0 and op!=1)or ra<1 or ra>16 or ca<0 or ca>16 or ra*ca>256)return -1;const count:usize=@intCast(ra*ca);const pb=3+count;if(n<pb+2)return -1;const rb=v[pb];const cb=v[pb+1];if(rb<1 or rb>16 or cb<0 or cb>16 or rb*cb>256 or n!=pb+2+@as(usize,@intCast(rb*cb)))return -1;for(0..count)|i|{if(v[3+i] < -1000000 or v[3+i]>1000000)return -1;}for(0..@as(usize,@intCast(rb*cb)))|i|{if(v[pb+2+i] < -1000000 or v[pb+2+i]>1000000)return -1;}if(ra!=rb or ca!=cb)return -1;const bytes=count*4;if(cap<bytes)return -2;for(0..count)|i|{const a=v[3+i];const b=v[pb+2+i];putI32(out,i*4,if(op==0)a+b else a-b);}return @intCast(count);}
